    const r = runCli(["check", deck]);
    assert.equal(r.status, 1, r.stdout + r.stderr);
    assert.match(r.stdout, /^構成案 outline\.md の書式の誤り:\n {2}\d+ 行目: /m);
  });

  test("文字が箱からはみ出しそうな箇所があると、一覧を示して終了コード 1 になる", () => {
    const deck = sandbox.copySample();
